import{_ as a,o as r,c as t,a3 as n}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"Terrain capture","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/terrain/docs/index.md"},"headers":[],"relativePath":"tools/terrain/docs/index.md","filePath":"tools/terrain/docs/index.md","lastUpdated":1791428389000}'),i={name:"tools/terrain/docs/index.md"};function s(o,e,c,d,p,l){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="terrain-capture" tabindex="-1">Terrain capture <a class="header-anchor" href="#terrain-capture" aria-label="Permalink to &quot;Terrain capture&quot;">​</a></h1><p><code>@pumpkin-plugins/terrain</code> provides terrain capture primitives and chunk-provider contracts without depending on Pumpkin APIs or Minecraft wire formats. A plugin supplies adapters for loading world data and for encoding the result.</p><h2 id="incremental-capture" tabindex="-1">Incremental capture <a class="header-anchor" href="#incremental-capture" aria-label="Permalink to &quot;Incremental capture&quot;">​</a></h2><p><code>TerrainCapture</code> samples a rectangular region within a caller-provided work budget on each step. It groups material runs into columns and can skip empty blocks above a configured height bound. Incremental work lets a plugin spread capture over server ticks instead of scanning an entire area at once.</p><p><code>AdaptiveWorkBudget</code> adjusts the work limit using rolling server MSPT and measured capture cost, while respecting the caller&#39;s ceiling. Use it when the workload should use spare tick time and back off as the server becomes busy.</p><h2 id="chunk-access-adapters" tabindex="-1">Chunk access adapters <a class="header-anchor" href="#chunk-access-adapters" aria-label="Permalink to &quot;Chunk access adapters&quot;">​</a></h2><p><code>ChunkLoader</code> and <code>TerrainGenerator</code> describe optional host capabilities. <code>acquireChunk</code> checks loaded chunks, requests a saved chunk when available, and requests generation only when the saved chunk is missing or loading is unavailable. Explicit unavailable providers let platforms expose their limits without pretending those operations succeeded.</p><p>The package does not load or generate chunks itself; its caller supplies the providers and decides how captured columns are stored or sent to clients.</p>',8)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
